examples.code:
answers = ["12", "twelve", "7"]
for text in answers:
    try:
        age = int(text)
        print("Age:", age)
    except ValueError:
        print(f"'{text}' is not a number.")

for text in ["5", "0", "five"]:
    try:
        print(100 / int(text))
    except ValueError:
        print("Not a number!")
    except ZeroDivisionError:
        print("Can't divide by zero!")

def set_hp(value):
    if value < 0:
        raise ValueError("Health can't be negative")
    return value

try:
    set_hp(-5)
except ValueError as err:
    print("Caught:", err)
finally:
    print("Check finished.")

tasks.solution:
text = "abc"

try:
    number = int(text)
    print(number * 2)
except ValueError:
    print("That's not a number!")

def safe_divide(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return None

print(safe_divide(10, 2))
print(safe_divide(10, 0))

try:
    age = int(input("How old are you? "))
    print("Your age:", age)
except ValueError:
    print("Please type digits.")

challenge.solution:
def set_level(level):
    if level < 1 or level > 10:
        raise ValueError("The level must be from 1 to 10")
    return level

print(set_level(3))

